"""`svg2png` from CairoSVG's API, drawn by `subako.svg_to_png` instead of
Cairo, which this build doesn't have. It makes `render_to_png` in pygal and
other libraries that call CairoSVG work. The rest of CairoSVG isn't here."""

import os
import secrets

import subako

__all__ = ["svg2png"]


def svg2png(
    bytestring=None,
    *,
    file_obj=None,
    url=None,
    write_to=None,
    scale=1,
    output_width=None,
    output_height=None,
    **_ignored,
):
    """Draw SVG given as `bytestring`, `file_obj` or a file path `url` as a
    PNG. Writes it to `write_to`, a path or a binary file object, or returns
    the bytes when that is None."""
    if bytestring is None:
        if file_obj is not None:
            bytestring = file_obj.read()
        elif url is not None:
            with open(url, "rb") as f:
                bytestring = f.read()
        else:
            raise TypeError("svg2png needs bytestring, file_obj or url")
    if output_width or output_height:
        scale = _scale_to(bytestring, output_width, output_height)
    if isinstance(write_to, (str, os.PathLike)):
        subako.svg_to_png(bytestring, write_to, scale=scale)
        return None
    path = f"/tmp/.subako-png-{secrets.token_hex(8)}.png"
    try:
        subako.svg_to_png(bytestring, path, scale=scale)
        with open(path, "rb") as f:
            png = f.read()
    finally:
        try:
            os.remove(path)
        except FileNotFoundError:
            pass
    if write_to is None:
        return png
    write_to.write(png)
    return None


def _scale_to(svg, width, height):
    """The scale that makes the image `width` wide or `height` high."""
    path = f"/tmp/.subako-png-{secrets.token_hex(8)}.png"
    try:
        own_width, own_height = subako.svg_to_png(svg, path)
    finally:
        try:
            os.remove(path)
        except FileNotFoundError:
            pass
    return width / own_width if width else height / own_height
